"""Bahasa Melayu — al-Quran (quran_001 … quran_080)."""

T = {
"quran_001": ("Apakah nama surah pertama dalam al-Quran?", ["Al-Fatihah", "Al-Baqarah", "Al-Ikhlas", "An-Nas"], "Al-Fatihah, «Pembukaan», ialah surah pertama dalam al-Quran."),
"quran_002": ("Berapakah jumlah surah dalam al-Quran?", ["114", "99", "100", "120"], "Al-Quran terdiri daripada 114 surah."),
"quran_003": ("Apakah surah terpanjang dalam al-Quran?", ["Al-Baqarah", "Al-Fatihah", "Al-Kauthar", "Al-'Asr"], "Al-Baqarah ialah surah terpanjang dalam al-Quran, dengan 286 ayat."),
"quran_004": ("Apakah surah terpendek dalam al-Quran?", ["Al-Kauthar", "Al-Ikhlas", "Al-'Asr", "An-Nasr"], "Al-Kauthar, dengan 3 ayat, ialah surah terpendek dalam al-Quran."),
"quran_005": ("Dalam bahasa apakah al-Quran diturunkan?", ["Arab", "Aram", "Ibrani", "Parsi"], "Al-Quran menyatakan dengan jelas bahawa ia diturunkan dalam bahasa Arab."),
"quran_006": ("Apakah nama surah ke-19, yang dinamakan sempena ibu Nabi Isa?", ["Maryam", "Yusuf", "Al-Kahfi", "Taha"], "Surah ke-19 al-Quran dinamakan Maryam, sempena ibu Nabi Isa."),
"quran_007": ("Apakah nama bagi satu bab dalam al-Quran?", ["Surah", "Hadis", "Juzuk", "Tafsir"], "Al-Quran dibahagikan kepada bab-bab yang dinamakan surah."),
"quran_008": ("Apakah nama bagi satu baris firman dalam al-Quran?", ["Ayat", "Surah", "Hadis", "Rukuk"], "Setiap baris firman dalam al-Quran dinamakan ayat, yang bermaksud «tanda»."),
"quran_009": ("Surah manakah yang wajib dibaca dalam setiap rakaat solat?", ["Al-Fatihah", "Al-Ikhlas", "Al-Kauthar", "Al-Fil"], "Membaca Al-Fatihah ialah rukun solat yang diriwayatkan dalam hadis sahih."),
"quran_010": ("Kepada siapakah al-Quran diturunkan?", ["Nabi Muhammad ﷺ", "Nabi Musa", "Nabi Isa", "Nabi Daud"], "Al-Quran diturunkan kepada Nabi Muhammad ﷺ melalui malaikat Jibril."),
"quran_011": ("Apakah nama ayat 255 surah Al-Baqarah yang terkenal?", ["Ayat Kursi", "Ayat An-Nur", "Ayat As-Siyam", "Ayat Ad-Dain"], "Ayat 2:255, Ayat Kursi, menggambarkan keagungan Allah: «Allah, tiada tuhan selain Dia, Yang Maha Hidup…»"),
"quran_012": ("Surah manakah yang tidak dimulakan dengan «Bismillahirrahmanirrahim»?", ["At-Taubah", "Al-Fatihah", "Yasin", "Al-Kahfi"], "At-Taubah (surah 9) ialah satu-satunya surah yang tidak dibuka dengan basmalah."),
"quran_013": ("Apakah tema ayat terpanjang dalam al-Quran (2:282)?", ["Penulisan hutang", "Ibadah haji", "Puasa", "Pusaka"], "Ayat terpanjang al-Quran mengajar supaya hutang ditulis dan saksi diambil: kejujuran dipelihara."),
"quran_014": ("Dengan perkataan apakah ayat-ayat pertama al-Quran yang diturunkan bermula?", ["Iqra' (Bacalah!)", "Qul (Katakanlah!)", "Sabbih (Sucikanlah!)", "Kutiba (Telah diwajibkan)"], "Ayat-ayat pertama yang diturunkan bermula dengan «Iqra'»: «Bacalah dengan nama Tuhanmu yang menciptakan.»"),
"quran_015": ("Menurut al-Quran, Lailatul Qadar lebih baik daripada berapa bulan?", ["Seribu bulan", "Seratus bulan", "Dua belas bulan", "Empat puluh bulan"], "«Lailatul Qadar lebih baik daripada seribu bulan»: satu malam Ramadan yang lebih bernilai daripada ibadah seumur hidup."),
"quran_016": ("Apakah nama dua surah terakhir, Al-Falaq dan An-Nas, yang dibaca untuk perlindungan?", ["Al-Mu'awwizatain (dua surah perlindungan)", "Az-Zahrawan", "Al-Mufassal", "As-Sab' At-Tiwal"], "Al-Falaq dan An-Nas dinamakan «al-mu'awwizatain»: keduanya dibaca untuk memohon perlindungan Allah."),
"quran_017": ("Kepada berapa bahagian (juzuk) al-Quran dibahagikan secara tradisi?", ["30", "10", "60", "114"], "Al-Quran dibahagikan kepada 30 juzuk, yang membantu mengkhatamkannya dalam sebulan, contohnya pada bulan Ramadan."),
"quran_018": ("Berapakah jumlah ayat surah Al-Fatihah?", ["7", "3", "10", "14"], "Al-Fatihah mempunyai tujuh ayat, dibaca dalam setiap rakaat solat."),
"quran_019": ("Surah manakah yang dinamakan sempena logam?", ["Al-Hadid (Besi)", "An-Nur (Cahaya)", "Ar-Ra'd (Guruh)", "Ad-Dukhan (Asap)"], "Surah 57 dinamakan Al-Hadid: «Kami turunkan besi yang padanya terdapat kekuatan yang hebat dan pelbagai manfaat bagi manusia.»"),
"quran_020": ("Kisah apakah yang al-Quran namakan «sebaik-baik kisah»?", ["Kisah Yusuf", "Kisah Nuh", "Kisah Ashabul Kahfi", "Kisah gajah"], "«Kami ceritakan kepadamu sebaik-baik kisah»: demikianlah kisah Yusuf dibuka."),
"quran_021": ("Berapakah jumlah ayat Al-Baqarah, surah terpanjang?", ["286", "114", "200", "365"], "Al-Baqarah mempunyai 286 ayat: surah terpanjang dalam al-Quran."),
"quran_022": ("Surah pendek manakah yang mengisytiharkan: «Katakanlah: Dialah Allah, Yang Maha Esa»?", ["Al-Ikhlas", "Al-Falaq", "An-Nas", "Al-Kauthar"], "Al-Ikhlas mengisytiharkan keesaan Allah yang sempurna dalam empat ayat."),
"quran_023": ("Dalam tempoh lebih kurang berapa tahun al-Quran diturunkan?", ["23 tahun", "1 tahun", "10 tahun", "40 tahun"], "Al-Quran diturunkan secara beransur-ansur selama lebih kurang 23 tahun, di Makkah kemudian di Madinah."),
"quran_024": ("Menurut al-Quran, apakah Rumah pertama yang dibina untuk manusia beribadah kepada Allah?", ["Kaabah, di Bakkah (Makkah)", "Masjid Quba'", "Baitulmaqdis", "Masjid Nabi ﷺ"], "«Sesungguhnya Rumah pertama yang dibina untuk manusia ialah yang di Bakkah, yang diberkati…»: Kaabah di Makkah."),
"quran_025": ("Surah manakah yang dinamakan sempena gajah?", ["Al-Fil", "An-Nahl", "An-Naml", "Al-Baqarah"], "Surah 105, Al-Fil («Gajah»), mengenang tentera bergajah Abrahah yang dihentikan sebelum sampai ke Makkah."),
"quran_026": ("Surah An-Nahl dinamakan sempena serangga apa?", ["Lebah", "Semut", "Labah-labah", "Lalat"], "An-Nahl bermaksud «lebah»; di dalamnya Allah mengilhamkan lebah untuk membina sarangnya (16:68)."),
"quran_027": ("Surah manakah yang dinamakan sempena semut?", ["An-Naml", "An-Nahl", "Al-'Ankabut", "Al-An'am"], "An-Naml («Semut», surah 27) menceritakan semut yang memberi amaran kepada kaumnya ketika tentera Sulaiman menghampiri."),
"quran_028": ("Dalam surah Al-'Ankabut, dengan apakah al-Quran mengumpamakan orang yang mengambil pelindung selain Allah?", ["Labah-labah yang membuat rumah yang rapuh", "Lebah yang membina sarangnya", "Semut yang menyimpan makanan", "Anjing yang termengah-mengah"], "«Sesungguhnya serapuh-rapuh rumah ialah rumah labah-labah» (29:41), yang menjadi nama surah ini."),
"quran_029": ("Surah Al-Baqarah dinamakan sempena haiwan apa?", ["Lembu betina", "Unta", "Kuda", "Biri-biri"], "Al-Baqarah («Lembu Betina») mengenang lembu yang diperintahkan disembelih oleh Bani Israil (2:67)."),
"quran_030": ("Apakah maksud tajuk surah 6, Al-An'am?", ["Binatang ternakan", "Burung-burung", "Taman-taman", "Bintang-bintang"], "Al-An'am bermaksud «binatang ternakan»; surah ini menyangkal peraturan rekaan kaum musyrik tentang ternakan."),
"quran_031": ("Ayat manakah yang diulang berkali-kali dalam surah Ar-Rahman?", ["«Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?»", "«Allah Maha Besar»", "«Katakanlah: Dialah Allah, Yang Maha Esa»", "«Segala puji bagi Allah»"], "Ulangan ini («Fa-bi-ayyi ala'i rabbikuma tukadzdziban») berulang 31 kali dalam surah 55."),
"quran_032": ("Menurut surah Al-Kahfi, berapa lama Ashabul Kahfi tidur?", ["Tiga ratus tahun, ditambah sembilan", "Seratus tahun", "Empat puluh tahun", "Seribu tahun"], "«Mereka tinggal di dalam gua mereka selama tiga ratus tahun, dan ditambah sembilan tahun» (18:25)."),
"quran_033": ("Haiwan apakah yang bersama Ashabul Kahfi?", ["Anjing", "Kucing", "Keldai", "Kambing"], "«Anjing mereka menghulurkan kedua-dua kaki hadapannya di muka pintu gua» (18:18)."),
"quran_034": ("Terhadap kaum manakah Zulkarnain membina tembok, menurut Al-Kahfi?", ["Ya'juj dan Ma'juj", "'Ad dan Tsamud", "Bangsa Rom", "Bangsa Parsi"], "Suatu kaum meminta perlindungannya daripada Ya'juj dan Ma'juj; dia membina tembok daripada besi dan tembaga (18:94-96)."),
"quran_035": ("Ayat manakah yang bermula dengan «Allah adalah cahaya langit dan bumi»?", ["Ayat Cahaya (An-Nur 24:35)", "Ayat Kursi", "Ayat Hutang", "Ayat Gua"], "«Ayat An-Nur» mengumpamakan cahaya-Nya seperti sebuah lubang dinding yang di dalamnya ada pelita (24:35)."),
"quran_036": ("Menurut hadis dalam al-Bukhari, surah manakah yang menyamai sepertiga al-Quran?", ["Al-Ikhlas", "Al-Fatihah", "Yasin", "Al-Kahfi"], "Nabi ﷺ bersabda tentang «Qul huwallahu ahad» bahawa ia «menyamai sepertiga al-Quran»."),
"quran_037": ("Ayat manakah yang Nabi ﷺ namakan sebagai ayat paling agung dalam al-Quran, menurut Sahih Muslim?", ["Ayat Kursi", "Ayat pertama Al-Fatihah", "Ayat terakhir Al-Baqarah", "Ayat Cahaya"], "Baginda bertanya kepada Ubai bin Ka'ab ayat mana yang paling agung; Ubai menjawab Ayat Kursi, dan Nabi ﷺ mengucapkan tahniah kepadanya."),
"quran_038": ("Musuh Nabi ﷺ yang manakah dinamakan dalam surah Al-Masad?", ["Abu Lahab", "Abu Jahal", "Abu Sufyan", "Al-Walid"], "«Binasalah kedua-dua tangan Abu Lahab» (111:1): bapa saudara Nabi ﷺ ini memusuhinya secara terang-terangan."),
"quran_039": ("Bagaimanakah surah Al-Kafirun berakhir?", ["«Bagi kamu agama kamu, dan bagiku agamaku»", "«Allah Maha Besar»", "«Dan tiada sesiapa pun yang setara dengan-Nya»", "«Daripada kejahatan orang yang dengki»"], "«Lakum dinukum wa liya din» (109:6) menyatakan pemisahan yang jelas antara Islam dan penyembahan berhala."),
"quran_040": ("Tentang apakah surah An-Nasr?", ["Pertolongan Allah dan manusia yang memasuki agama-Nya secara berbondong-bondong", "Penciptaan langit", "Puasa Ramadan", "Kisah Yusuf"], "«Apabila datang pertolongan Allah dan kemenangan, dan engkau melihat manusia memasuki agama Allah secara berbondong-bondong» (110:1-2)."),
"quran_041": ("Menurut surah Al-'Asr, siapakah yang selamat daripada kerugian?", ["Orang yang beriman, beramal soleh, dan saling berpesan dengan kebenaran dan kesabaran", "Orang yang kaya", "Orang yang kuat", "Orang yang bermusafir"], "«Sesungguhnya manusia dalam kerugian, kecuali orang yang beriman dan beramal soleh, dan saling berpesan dengan kebenaran dan kesabaran» (103:2-3)."),
"quran_042": ("Dalam surah Al-Ma'un, apakah yang dilakukan «orang yang mendustakan hari Pembalasan»?", ["Dia menghalau anak yatim dan tidak menggalakkan memberi makan orang miskin", "Dia merobohkan masjid", "Dia enggan bermusafir", "Dia berdusta tentang hartanya"], "«Itulah orang yang menghalau anak yatim dan tidak menggalakkan memberi makan orang miskin» (107:2-3)."),
"quran_043": ("Menurut ayat-ayat pertama yang diturunkan (Al-'Alaq), daripada apakah Allah menciptakan manusia?", ["Segumpal darah ('alaq)", "Cahaya", "Api", "Angin"], "«Bacalah dengan nama Tuhanmu yang menciptakan, Dia menciptakan manusia daripada segumpal darah» (96:1-2)."),
"quran_044": ("Apakah yang dimaksudkan ungkapan al-Quran «tujuh ayat yang diulang-ulang» (as-sab' al-mathani)?", ["Al-Fatihah", "Tujuh surah terpanjang", "Ayat Kursi", "Tujuh ayat terakhir al-Quran"], "«Kami telah berikan kepadamu tujuh ayat yang diulang-ulang dan al-Quran yang agung» (15:87): Al-Fatihah, dibaca dalam setiap rakaat."),
"quran_045": ("Apakah maksud «Al-Furqan», salah satu nama al-Quran?", ["Pembeza (antara yang benar dan yang batil)", "Cahaya", "Peringatan", "Penyembuh"], "«Maha Berkat Tuhan yang menurunkan Al-Furqan kepada hamba-Nya» (25:1): Kitab yang memisahkan kebenaran daripada kebatilan."),
"quran_046": ("Dengan apakah Allah bersumpah pada permulaan surah At-Tur?", ["Demi Gunung (Tur)", "Demi matahari", "Demi buah tin", "Demi malam"], "«Demi Gunung! Dan demi Kitab yang tertulis…» (52:1-2): Tur ialah gunung tempat Musa menerima wahyu."),
"quran_047": ("Apakah maksud «An-Najm», tajuk surah 53?", ["Bintang", "Bulan", "Matahari", "Fajar"], "«Demi bintang ketika ia terbenam!» (53:1)."),
"quran_048": ("Menurut surah Al-Qadr, siapakah yang turun pada Lailatul Qadar?", ["Para malaikat dan Ruh (Jibril)", "Para nabi", "Jin", "Angin"], "«Pada malam itu turun para malaikat dan Ruh dengan izin Tuhan mereka» (97:4)."),
"quran_049": ("Menurut al-Quran, apakah al-Quran bagi orang beriman?", ["Penyembuh dan rahmat", "Sekadar syair", "Buku sejarah", "Kalendar"], "«Kami turunkan daripada al-Quran sesuatu yang menjadi penyembuh dan rahmat bagi orang beriman» (17:82)."),
"quran_050": ("Cabaran apakah yang al-Quran kemukakan kepada orang yang meragui asal usulnya daripada Allah?", ["Menghasilkan satu surah sahaja yang seumpamanya", "Menghafal seluruh al-Quran", "Menterjemahkan al-Quran", "Membina masjid"], "«Jika kamu ragu-ragu tentang apa yang Kami turunkan, maka buatlah satu surah yang seumpamanya» (2:23)."),
"quran_051": ("Surah manakah yang dinamakan «Ummul Quran» (Induk al-Quran)?", ["Al-Fatihah", "Al-Baqarah", "Yasin", "Al-Ikhlas"], "Nabi ﷺ bersabda: «Ummul Quran ialah tujuh ayat yang diulang-ulang dan al-Quran yang agung.»"),
"quran_052": ("Apakah surah «Makkiyah»?", ["Surah yang diturunkan sebelum Hijrah", "Surah yang diturunkan di Madinah", "Surah tentang Kaabah", "Surah yang sangat pendek"], "Para ulama mengelaskan surah mengikut zaman: sebelum hijrah ke Madinah (Makkiyah) atau selepasnya (Madaniyah)."),
"quran_053": ("Berapa surah yang bermula dengan huruf «Alif, Lam, Mim»?", ["Enam", "Dua", "Sepuluh", "Satu"], "Al-Baqarah, Ali 'Imran, Al-'Ankabut, Ar-Rum, Luqman dan As-Sajdah dibuka dengan «Alif, Lam, Mim»."),
"quran_054": ("Apakah nama huruf-huruf terpisah yang membuka sesetengah surah (Alif Lam Mim, Yasin, Qaf…)?", ["Huruf-huruf muqatta'ah", "Ayat-ayat yang dimansuhkan", "Huruf syamsiah", "Huruf tajwid"], "Dua puluh sembilan surah dibuka dengan huruf-huruf ini, yang maknanya yang sebenar hanya diketahui Allah."),
"quran_055": ("Surah manakah yang dinamakan sempena Nabi Muhammad ﷺ?", ["Surah 47, Muhammad", "Surah 1, Al-Fatihah", "Surah 36, Yasin", "Surah 112, Al-Ikhlas"], "Surah 47 dinamakan «Muhammad»; ia menyebut namanya dalam ayat 2."),
"quran_056": ("Apakah nasihat pertama Luqman kepada anaknya, yang dipetik dalam al-Quran?", ["Jangan mempersekutukan Allah dengan sesuatu pun", "Pelajari bintang-bintang", "Jadilah pedagang", "Bermusafirlah jauh"], "«Wahai anakku, janganlah engkau mempersekutukan Allah; sesungguhnya syirik itu kezaliman yang besar» (31:13)."),
"quran_057": ("Dengan nama lain apakah surah At-Taubah dikenali?", ["Bara'ah (Pemutusan hubungan)", "An-Nur", "Al-Anfal", "Al-Fath"], "Perkataan pertamanya ialah «Bara'ah»: pengisytiharan pemutusan hubungan daripada Allah dan Rasul-Nya terhadap kaum musyrik (9:1)."),
"quran_058": ("Surah manakah yang bermula dengan dua huruf «Ya, Sin»?", ["Yasin (surah 36)", "Taha", "Qaf", "Sad"], "Surah 36 dibuka dengan «Yasin. Demi al-Quran yang penuh hikmah!»"),
"quran_059": ("Apakah maksud «Al-Mulk», tajuk surah 67?", ["Kerajaan / Kekuasaan", "Cahaya", "Perjalanan", "Kemenangan"], "«Maha Berkat Tuhan yang menguasai segala kerajaan (al-Mulk)» (67:1)."),
"quran_060": ("Apakah surah terakhir dalam al-Quran?", ["An-Nas", "Al-Falaq", "Al-Ikhlas", "Al-Fatihah"], "An-Nas («Manusia»), surah 114, menutup al-Quran: «Katakanlah: Aku berlindung kepada Tuhan manusia»."),
"quran_061": ("Bagaimanakah surah Al-Falaq bermula?", ["«Katakanlah: Aku berlindung kepada Tuhan yang menguasai subuh»", "«Katakanlah: Dialah Allah, Yang Maha Esa»", "«Demi masa!»", "«Segala puji bagi Allah»"], "«Qul a'uzu birabbil-falaq» (113:1): Al-Falaq bermaksud waktu subuh."),
"quran_062": ("Dua bukit manakah yang al-Quran namakan antara «syiar-syiar Allah»?", ["Safa dan Marwah", "Uhud dan Tsur", "Arafah dan Mina", "Hira dan Abu Qubais"], "«Sesungguhnya Safa dan Marwah itu sebahagian daripada syiar Allah» (2:158): sa'i dalam ibadah haji dilakukan di antara keduanya."),
"quran_063": ("Siapakah satu-satunya wanita yang disebut namanya dalam al-Quran?", ["Maryam", "Khadijah", "Asiah", "Hajar"], "Maryam, ibu Isa, disebut dalam beberapa surah, dan satu surah penuh menyandang namanya."),
"quran_064": ("Siapakah satu-satunya sahabat Nabi ﷺ yang disebut namanya dalam al-Quran?", ["Zaid bin Harithah", "Abu Bakar", "Umar", "Ali"], "«Maka apabila Zaid telah menyelesaikan keperluannya terhadap isterinya…» (33:37): Zaid, hamba yang dimerdekakan Nabi, satu-satunya sahabat yang dinamakan."),
"quran_065": ("Siapakah Harut dan Marut, yang disebut dalam surah Al-Baqarah?", ["Dua malaikat yang diutus ke Babil", "Dua nabi", "Dua raja Mesir", "Dua sahabat"], "«…apa yang diturunkan kepada dua malaikat di negeri Babil, iaitu Harut dan Marut» (2:102): mereka memberi amaran bahawa sihir adalah ujian."),
"quran_066": ("Menurut al-Quran, siapakah yang paling mulia di sisi Allah?", ["Yang paling bertakwa", "Yang paling kaya", "Yang paling kuat", "Yang paling terkenal"], "«Sesungguhnya orang yang paling mulia di sisi Allah dalam kalangan kamu ialah orang yang paling bertakwa» (49:13)."),
"quran_067": ("Apakah yang dimaksudkan «Al-Waqi'ah», tajuk surah 56?", ["Peristiwa yang pasti berlaku (hari Kiamat)", "Kafilah", "Semut", "Perjalanan malam"], "«Apabila berlaku hari Kiamat…» (56:1): surah ini menggambarkan tiga golongan pada hari Akhir."),
"quran_068": ("Dengan benda apakah Allah bersumpah pada permulaan surah Al-Qalam?", ["Demi pena", "Demi pedang", "Demi neraca", "Demi pelita"], "«Nun. Demi pena dan apa yang mereka tuliskan!» (68:1)."),
"quran_069": ("Bagaimanakah surah Al-Fajr dibuka?", ["Dengan sumpah demi fajar dan sepuluh malam", "Dengan sumpah demi buah tin", "Dengan kisah Yusuf", "Dengan basmalah sahaja"], "«Demi fajar! Dan demi malam yang sepuluh!» (89:1-2)."),
"quran_070": ("Dengan benda langit apakah Allah bersumpah pada permulaan surah Asy-Syams?", ["Matahari", "Bulan sahaja", "Bintang-bintang", "Planet-planet"], "«Demi matahari dan cahayanya di pagi hari!» (91:1); Asy-Syams bermaksud «matahari»."),
"quran_071": ("Surah manakah yang dibuka dengan: «Bukankah telah berlalu kepada manusia satu masa yang ketika itu dia belum menjadi sesuatu yang dapat disebut?»", ["Al-Insan (surah 76)", "Al-Kahfi", "Al-Hajj", "Al-Fatihah"], "Al-Insan («Manusia»), juga dinamakan Ad-Dahr, mengingatkan bahawa manusia bukan apa-apa sebelum diciptakan (76:1)."),
"quran_072": ("Menurut al-Quran, untuk apakah Allah memudahkan al-Quran?", ["Untuk diingati dan dihafal", "Untuk berdagang", "Untuk diterjemahkan", "Untuk dilupakan"], "«Sesungguhnya Kami telah memudahkan al-Quran untuk peringatan, maka adakah orang yang mahu mengambil pelajaran?» (54:17), diulang empat kali dalam surah itu."),
"quran_073": ("Tanda apakah yang surah Al-Qamar sebutkan dalam ayat pertamanya?", ["Bulan terbelah", "Matahari padam", "Laut terbelah", "Gunung berbicara"], "«Telah hampir saat (Kiamat), dan bulan telah terbelah» (54:1): satu tanda yang ditunjukkan kepada penduduk Makkah."),
"quran_074": ("Mengapakah al-Quran diturunkan secara beransur-ansur dan bukan sekaligus, menurut al-Quran sendiri?", ["Untuk meneguhkan hati Nabi ﷺ", "Kerana ia terlalu panjang", "Untuk menyembunyikannya daripada musuh", "Kerana perjalanan"], "«Demikianlah, supaya Kami meneguhkan hatimu dengannya, dan Kami membacakannya secara tartil» (25:32)."),
"quran_075": ("Surah manakah yang Nabi ﷺ baca ke dalam kedua-dua tangannya setiap malam sebelum tidur, menurut Aisyah?", ["Al-Ikhlas, Al-Falaq dan An-Nas", "Al-Fatihah dan Al-Baqarah", "Yasin dan Al-Mulk", "Al-Kahfi dan Maryam"], "Baginda meniup ke dalam kedua-dua tangannya sambil membaca tiga surah «Qul», kemudian menyapukannya ke seluruh tubuh, tiga kali."),
"quran_076": ("Apakah nama sujud yang dilakukan ketika membaca ayat-ayat tertentu dalam al-Quran?", ["Sujud tilawah", "Sujud sahwi", "Sujud syukur", "Rukuk"], "Al-Quran mengandungi ayat-ayat sajdah, seperti ayat terakhir Al-'Alaq: «sujudlah dan dekatkanlah dirimu» (96:19)."),
"quran_077": ("Apakah nama ilmu tentang kaedah menyebut al-Quran dengan betul?", ["Tajwid", "Tafsir", "Fiqh", "Sirah"], "Tajwid mengajar cara menyebut setiap huruf daripada makhrajnya, beserta sifat-sifatnya."),
"quran_078": ("Apakah nama orang yang telah menghafal seluruh al-Quran?", ["Hafiz", "Imam", "Muazin", "Mufti"], "Hafiz bermaksud «penjaga»: dia membawa seluruh al-Quran dalam ingatannya."),
"quran_079": ("Apakah nama naskhah bertulis al-Quran?", ["Mushaf", "Hadis", "Juzuk", "Mimbar"], "Mushaf ialah al-Quran yang dihimpunkan antara dua kulit; juzuk ialah salah satu daripada tiga puluh bahagiannya."),
"quran_080": ("Dalam surah manakah basmalah muncul dua kali?", ["An-Naml", "Al-Fatihah", "At-Taubah", "Al-Baqarah"], "Selain pada pembukaannya, An-Naml memetik basmalah pada permulaan surat Sulaiman kepada Ratu Saba' (27:30)."),
}
